SELECT * FROM
where 1 = 1 and alarm_level = #{warnLevel, jdbcType=INTEGER} and conf_mode = #{confMode, jdbcType=INTEGER} and device_name like concat("%",#{deviceName, jdbcType=VARCHAR},"%") and alarm_time BETWEEN #{startTime, jdbcType=TIMESTAMP} AND #{endTime, jdbcType=TIMESTAMP}
AND (CASE WHEN #{alarmSource, jdbcType=INTEGER} = 888 THEN alarm_source = 888 WHEN #{alarmSource, jdbcType=INTEGER} = 279 THEN alarm_source = 279 WHEN #{alarmSource, jdbcType=INTEGER} != 279 and #{alarmSource, jdbcType=INTEGER} != 888 THEN alarm_source != 888 and alarm_source != 279 END)

SELECT DATE_FORMAT( warn_time, '%Y-%m-%d' ) as time_node, count( * ) as count FROM ( select a.warn_time from t_warn_info a where 1=1
union all( select f.alarm_time from t_robot_alarm f where 1=1
)union all( select h.alarm_time from t_camera_alarm h where 1=1 ) ) AS Time WHERE period_diff( date_format( now( ) , '%Y-%m-%d %H:%i:%S' ) , date_format( warn_time, '%Y-%m-%d %H:%i:%S' ) ) =0 and DATE_FORMAT( warn_time, '%Y-%m-%d %H:%i:%S' ) BETWEEN #{startTime} and #{endTime} GROUP BY time_node

SELECT * FROM

where 1 = 1
 and warn_id = #{warnId, jdbcType=BIGINT}
